    },
    {
      "name": "GTK 桌面界面",
      "description": "基于 GTK 3 + PyGObject 的完整桌面 UI，包含种子添加/管理/详情、筛选/搜索、速度图、系统托盘、菜单栏、偏好设置等完整交互，支持拖放添加种子。",
      "evidence": ["deluge/ui/gtk3/gtkui.py", "deluge/ui/gtk3/mainwindow.py", "deluge/ui/gtk3/systemtray.py", "deluge/ui/gtk3/glade/"]
    },
    {
      "name": "Web 远程管理界面",
      "description": "基于 Twisted Web 的内置 HTTP 服务器，提供 ExtJS 前端 SPA 界面（含 JSON API），可通过浏览器远程管理种子和设置。支持 HTTPS、密码认证、多主题。",
      "evidence": ["deluge/ui/web/server.py", "deluge/ui/web/json_api.py", "deluge/ui/web/js/", "deluge/ui/web/web.py"]
    },
    {
      "name": "命令行控制台",
      "description": "基于 curses 的 TUI 控制台界面，提供交互式命令行操作，支持种子列表浏览、详情查看、命令执行，以及非交互式的单命令模式。",
      "evidence": ["deluge/ui/console/console.py", "deluge/ui/console/main.py", "deluge/ui/console/cmdline/", "deluge/ui/console/modes/"]
    },
    {
      "name": "插件系统",
      "description": "内置插件框架，支持扩展核心功能。自带 AutoAdd（自动添加）、Blocklist（IP 屏蔽）、Execute（事件触发命令）、Extractor（解压）、Label、Notifications、Scheduler、Stats 等插件。",
      "evidence": ["deluge/plugins/", "deluge/pluginmanagerbase.py", "deluge/core/pluginmanager.py"]
    },
    {
      "name": "国际化 (i18n)",
      "description": "完整的多语言支持，通过 GNU gettext 实现界面翻译，覆盖数十种语言。",
      "evidence": ["deluge/i18n/", "deluge/i18n/util.py", "deluge/ui/data/share/"]
    }
  ],
  "domain": "网络 / P2P 文件共享",
  "target_users": "需要 BitTorrent 下载功能的桌面和服务器用户，特别是需要远程管理、多种界面的高级用户"
}
